// Config: edit these values once. Every other node reads them via $('Config').first().json
// If n8n runs in Docker and Neo4j/Ollama run on the host, use host.docker.internal.
// If n8n runs directly on Windows (npm / desktop), use localhost.
return [{
  json: {
    neo4j_url: 'http://host.docker.internal:7474',
    neo4j_db: 'neo4j',
    ollama_url: 'http://host.docker.internal:11434',
    embed_model: 'nomic-embed-text',
    // Scryfall set code(s) to ingest. One set is ~250-300 cards. Space separated for several: 'fdn dsk'
    set_codes: 'fdn',
    // Paste the current TXT link from https://magic.wizards.com/en/rules
    cr_url: 'PASTE_COMPREHENSIVE_RULES_TXT_URL_HERE',
  },
}];

const input = $('Start').first().json;
const s = v => (v === undefined || v === null || String(v).trim() === '' ? null : String(v).trim());
const n = v => (s(v) === null || isNaN(Number(v)) ? null : Number(v));
const params = {
  type: s(input.type), subtype: s(input.subtype), keyword: s(input.keyword),
  min_mv: n(input.min_mana_value), max_mv: n(input.max_mana_value),
  colors: (s(input.colors) ?? '').toUpperCase().replace(/[^WUBRG]/g, '').split('').filter(Boolean),
  exact_colors: String(input.exact_colors).toLowerCase() === 'true',
  rarity: s(input.rarity), set: s(input.set), format: s(input.format), text: s(input.text_contains),
  limit: Math.min(Math.max(parseInt(input.limit) || 15, 1), 40),
};
const statement = "MATCH (c:Card)
WHERE ($type IS NULL OR EXISTS { MATCH (c)-[:IS_TYPE]->(t:CardType) WHERE toLower(t.name) = toLower($type) })
  AND ($subtype IS NULL OR EXISTS { MATCH (c)-[:HAS_SUBTYPE]->(st:Subtype) WHERE toLower(st.name) = toLower($subtype) })
  AND ($keyword IS NULL OR EXISTS { MATCH (c)-[:HAS_KEYWORD]->(kw:Keyword) WHERE toLower(kw.name) = toLower($keyword) })
  AND ($min_mv IS NULL OR c.mana_value >= $min_mv)
  AND ($max_mv IS NULL OR c.mana_value <= $max_mv)
  AND (size($colors) = 0 OR ALL(x IN $colors WHERE EXISTS { MATCH (c)-[:HAS_COLOR]->(:Color {code: x}) }))
  AND (NOT $exact_colors OR COUNT { (c)-[:HAS_COLOR]->(:Color) } = size($colors))
  AND ($rarity IS NULL OR c.rarity = toLower($rarity))
  AND ($set IS NULL OR EXISTS { MATCH (c)-[:PRINTED_IN]->(s:Set) WHERE s.code = toLower($set) })
  AND ($format IS NULL OR EXISTS { MATCH (c)-[:LEGAL_IN]->(f:Format) WHERE f.name = toLower($format) })
  AND ($text IS NULL OR toLower(c.oracle_text) CONTAINS toLower($text))
WITH c ORDER BY c.mana_value, c.name
WITH collect(c) AS cards
RETURN size(cards) AS total_matches,
       [x IN cards[0..$limit] | {
          name: x.name, mana_cost: x.mana_cost, type_line: x.type_line,
          oracle_text: x.oracle_text, power: x.power, toughness: x.toughness,
          rarity: x.rarity, source: x.scryfall_uri
       }] AS cards";
return [{ json: { statements: [{ statement, parameters: params }] } }];

// Turns the Neo4j HTTP response into plain objects for the agent.
const res = $input.first().json;
if (res.errors?.length) throw new Error('Neo4j error: ' + JSON.stringify(res.errors));
const r = res.results[0];
let rows = r.data.map(d => Object.fromEntries(r.columns.map((c, i) => [c, d.row[i]])));
if (rows.length && 'score' in rows[0]) rows.sort((a, b) => b.score - a.score);
return [{ json: { count: rows.length, results: rows } }];
